// Build the send queue: the first N leads in the sheet that have not been emailed yet.
// "Chronological" = sheet order, top to bottom. Rows arrive from the Sheets node in that order.

const LIMIT = 75;             // <- how many emails this run sends. Raise once a test run looks right.
const STATUS_COL = 'Status';  // <- column that marks a lead as handled
const EMAIL_COL  = 'Email';

// Never email these, whatever the sheet says. Both went out twice already while
// the sheet write was silently failing. Delete a line to put one back in play.
const SKIP_EMAILS = new Set([
  'info@bisazza.com',       // Bisazza
  'myqueryto@cescauk.org',  // Cesca Accounting
]);

const seen = new Set();
const queue = [];

for (const item of $input.all()) {
  const row = item.json;

  const email  = String(row[EMAIL_COL] ?? '').trim().toLowerCase();
  const status = String(row[STATUS_COL] ?? '').trim();

  if (!email || !email.includes('@')) continue;  // no usable address
  if (SKIP_EMAILS.has(email)) continue;          // manually excluded
  if (status) continue;                          // already emailed / skipped / bounced
  if (seen.has(email)) continue;                 // same address twice in the list

  seen.add(email);
  queue.push({ json: { ...row, _to: email } });

  if (queue.length >= LIMIT) break;
}

if (queue.length === 0) {
  throw new Error('Nothing to send: every row either has no email or already has a Status.');
}

return queue;

// Fires once, after the last lead. The sheet is the real record; this just totals it up.
const processed = $input.all();
const queued = $('Build send queue').all().length;

const failures = [];
let echoed = 0;   // rows the Sheets node actually handed back
for (const it of processed) {
  const row = it.json ?? {};
  const status = String(row['Status'] ?? '').trim();
  if (status) echoed++;
  if (status === 'Failed') {
    failures.push({
      business: row['Business'] ?? '',
      email: row['Email'] ?? '',
      error: row['Send error'] ?? '',
    });
  }
}

const sent = processed.length - failures.length;

return [{ json: {
  queued,
  sent,
  failed: failures.length,
  notReached: queued - processed.length,   // >0 means the run stopped early
  failures,
  finishedAt: $now.toISO(),
  note: (echoed === 0
    ? `The Sheets node returned empty rows, so sent/failed here are counts of loop passes, not statuses - read the Status column for the truth. `
    : `Sheet column "Status" is the record: ${sent} rows now say Emailed, ${failures.length} say Failed. `) +
    `Pressing Execute again skips every row that already has a Status, so it resumes instead of re-sending.`,
} }];

// Turn one sheet row into a subject + HTML body.

const FC_URBAN_URL = 'https://www.fcurban.com/groups-and-company-pitch-rental/football-pitch-rental-for-groups-corporates';

// Venue name (exactly as it appears in the sheet) -> its fcurban.com slug.
// Every slug below was taken from fcurban.com/sitemap.xml and confirmed to
// return HTTP 200 with a page title matching the venue. A venue missing from
// this map renders as plain text, never as a broken link.
const VENUE_BASE = 'https://www.fcurban.com/location/';
const VENUE_SLUGS = {
