// One-line opt-out kept for UK PECR / GDPR cover. Set to '' to drop it.
const OPT_OUT = 'Reply with "no thanks" and I won\'t contact you again.';

const row = $json;
// Drop a trailing parenthetical so it does not read "Hi MOO Print Limited (UK) team,".
const business = (String(row['Business'] ?? '').replace(/\s*\([^)]*\)\s*$/, '').trim()
                  || String(row['Business'] ?? '').trim() || 'there');
const venue = String(row['Nearest FC Urban venue'] ?? '').trim();
const city  = String(row['City'] ?? '').trim() || 'your city';
const walk  = Number(row['Walk (min)']);

// WhatsApp only delivers to mobiles. ~90% of this sheet is landlines, so most
// rows return '' here and get routed past the WhatsApp branch by the IF node.
function mobileE164(raw) {
  const d = String(raw ?? '').replace(/[^\d+]/g, '');
  if (!d.startsWith('+')) return '';
  const n = d.slice(1);
  const isMobile =
       /^447\d{9}$/.test(n)        // UK
    || /^316\d{8}$/.test(n)        // NL
    || /^467\d{8}$/.test(n)        // SE
    || /^491[5-7]\d{7,9}$/.test(n) // DE
    || /^34[67]\d{8}$/.test(n)     // ES
    || /^324\d{8}$/.test(n);       // BE
  return isMobile ? n : '';
}
const waTo = mobileE164(row['Phone (international)']);

// Company names carry & and the odd quote - escape before they touch HTML.
const esc = (t) => String(t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const link = (text, url) => url ? `<a href="${esc(url)}">${esc(text)}</a>` : esc(text);

// Only claim a distance the sheet actually gives us.
let proximity;
if (venue && Number.isFinite(walk) && walk > 0) {
  proximity = `We already organise games at ${esc(venue)}, around a ${walk}-minute walk from your office.`;
} else if (venue) {
  proximity = `We already organise games at ${esc(venue)}, just around the corner from your office.`;
} else {
  proximity = `We already organise games across ${esc(city)}.`;
}

const venueSlug = VENUE_SLUGS[venue];
const venueLink = venue ? link(venue, venueSlug ? VENUE_BASE + venueSlug : '') : esc(city);
const closing = `You can find more information about ${link('FC Urban', FC_URBAN_URL)}`
              + ` and our venue at ${venueLink}.`;

const subject = `After work football for the ${business} team`;

const paras = [
  `Hi ${esc(business)} team,`,
  `I'm Joe from FC Urban. We organise social football games across ${esc(city)} where people can simply turn up and play.`,
  proximity,
  `We are looking for someone within ${esc(business)} who might be interested in helping us start a regular after-work football group for colleagues.`,
  `FC Urban takes care of the pitch, tops up the group with players if needed, and handles the payments and organisation. We mainly need someone internally who enjoys football and can help bring colleagues together and spread the word.`,
  `Would you be able to connect me with whoever looks after employee wellbeing, engagement or staff socials in ${esc(city)}?`,
  closing,
  `Best,`,
  `Joe<br>FC Urban`,
];
if (OPT_OUT) paras.push(`<span style="color:#888;font-size:12px">${esc(OPT_OUT)}</span>`);

const html = paras.map((p) => `<p>${p}</p>`).join('\n');

return { json: { ...row, to: row._to, waTo, waName: business, waVenue: venue || city, subject, html } };

